def siren_ringing(env):
    return bool(env.siren_ringing)

def switch_toggled(env):
    return any(event == "toggle" for event in env.events_this_step)

def holding_box(env):
    return env.carrying is not None and env.carrying.type == "box"

def box_fell(env):
    return any(event == "fall" for event in env.events_this_step)

def at_exit(env):
    return env.grid.get(env.agent_pos[0], env.agent_pos[1]) is not None and env.grid.get(env.agent_pos[0], env.agent_pos[1]).type == "goal"
